const webhookData = $('Webhook BA Analyze').first().json;
const body = webhookData.body || webhookData;
const client = $('Upsert BA Client').first().json;

return [{
  json: {
    client_id: client.id,
    prospect_id: body.prospect_id,
    company_name: body.company_name,
    sector: body.sector || '',
    location: body.location || '',
    site_web: body.site_web || '',
    nom_mission: `Analyse Phase 1 — ${body.company_name}`,
    callback_url: body.callback_url,
  }
}];

const ctx = $('Prepare Context').first().json;
const mission = $('Create BA Mission').first().json;

return [{
  json: {
    mission_id: mission.id,
    client_id: ctx.client_id,
    client_nom: ctx.company_name,
    nom_mission: ctx.nom_mission,
    site_web: ctx.site_web,
    secteur: ctx.sector,
    localisation: ctx.location,
    prospect_id: ctx.prospect_id,
    callback_url: ctx.callback_url,
  }
}];

const mission = $('Merge Final Context').first().json;
const SERPER_KEY = $env.SERPER_API_KEY;

let siteContent = 'Site non accessible';
if (mission.site_web) {
  try {
    const siteResp = await this.helpers.httpRequest({
      method: 'GET',
      url: mission.site_web,
      timeout: 10000,
      returnFullResponse: false,
    });
    const html = typeof siteResp === 'string' ? siteResp : JSON.stringify(siteResp);
    siteContent = html
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .substring(0, 8000);
  } catch (e) {
    siteContent = 'Site non accessible';
  }
}

async function serperSearch(context, query) {
  try {
    const data = await context.helpers.httpRequest({
      method: 'POST',
      url: 'https://google.serper.dev/search',
      headers: { 'X-API-KEY': SERPER_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({ q: query, gl: 'fr', hl: 'fr', num: 5 }),
    });
    const results = data.organic || [];
    return results.slice(0, 5).map(function(r) { return '- ' + r.title + ': ' + r.snippet; }).join('\n');
  } catch (e) {
    return 'Recherche echouee';
  }
}

const clientNom = mission.client_nom || '';
const secteur = mission.secteur || '';

const searchInfos = await serperSearch(this, clientNom + ' entreprise informations chiffres cles site officiel');
const searchActus = await serperSearch(this, clientNom + ' actualites 2025 2026');
const searchSecteur = await serperSearch(this, clientNom + ' ' + secteur + ' marche concurrents');

const prompt = 'Tu es un analyste business senior specialise dans le conseil aux entreprises. A partir des informations ci-dessous, produis une fiche identite client enrichie au format JSON strict. Reponds UNIQUEMENT avec le JSON, sans backticks, sans texte avant ou apres.\n\n'
  + '## DONNEES CLIENT\n'
  + 'Nom: ' + clientNom + '\n'
  + 'Secteur: ' + secteur + '\n'
  + 'Site web: ' + (mission.site_web || 'Non renseigne') + '\n'
  + 'Localisation: ' + (mission.localisation || 'Non renseigne') + '\n\n'
  + '## CONTENU DU SITE WEB\n' + siteContent + '\n\n'
  + '## RECHERCHE - Infos entreprise\n' + searchInfos + '\n\n'
  + '## RECHERCHE - Actualites recentes\n' + searchActus + '\n\n'
  + '## RECHERCHE - Secteur et concurrents\n' + searchSecteur + '\n\n'
  + '## FORMAT JSON ATTENDU\n'
  + '{"identite":{"nom_complet":"","forme_juridique":"","date_creation":"","siege_social":"","dirigeants":[""],"effectif_estime":"","ca_estime":"","code_naf":""},"positionnement":{"activite_principale":"","clients_types":"","proposition_valeur":"","zone_geographique":""},"signaux":{"actualites_recentes":[""],"tendance_croissance":"","recrutements_recents":"","indices_maturite_digitale":""},"contexte_sectoriel":{"secteur":"","concurrents_identifies":[""],"tendances_sectorielles":""},"synthese_consultant":""}\n\n'
  + 'Si une information n est pas trouvee, ecris Non trouve.';

const body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 4096,
  temperature: 0.2,
  messages: [{ role: 'user', content: prompt }]
};

return [{
  json: {
    api_body: JSON.stringify(body),
    mission_id: mission.mission_id,
    client_id: mission.client_id,
    client_nom: clientNom,
    nom_mission: mission.nom_mission,
    prospect_id: mission.prospect_id,
    callback_url: mission.callback_url,
  }
}];

const response = $input.first().json;
const raw = response.content?.[0]?.text || '';
const prev = $('Scrape + Search + Préparer LLM').first().json;
const usage = response.usage || {};

// Remove markdown code blocks
let cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
// Extract JSON object even if there's surrounding text
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start !== -1 && end !== -1 && end > start) {
  cleaned = cleaned.slice(start, end + 1);
}

try {
  const enriched = JSON.parse(cleaned);
  const jsonString = JSON.stringify(enriched).replace(/'/g, "''");
  return [{ json: {
    enriched_data: enriched,
    enriched_json_string: jsonString,
    parse_success: true,
    mission_id: prev.mission_id, client_id: prev.client_id,
    client_nom: prev.client_nom, nom_mission: prev.nom_mission,
    prospect_id: prev.prospect_id, callback_url: prev.callback_url,
    tokens_input: usage.input_tokens || 0, tokens_output: usage.output_tokens || 0
  }}];
} catch (e) {
  return [{ json: {
    enriched_data: null, enriched_json_string: null,
    raw_response: raw, parse_success: false, parse_error: e.message,
    mission_id: prev.mission_id, client_id: prev.client_id,
    client_nom: prev.client_nom, nom_mission: prev.nom_mission,
    prospect_id: prev.prospect_id, callback_url: prev.callback_url,
    tokens_input: usage.input_tokens || 0, tokens_output: usage.output_tokens || 0
  }}];
}

